#pragma once
// Palette entries for the physical-surface nodes. NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after pin()/attr()
// are defined, and calls appendPhysicalSurfaceNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphPhysicalSurfaceNodeTable.cs pin for pin (docs/plans/wave11/SHAPES_MATERIALS.md,
// Aver Node family "PhysicalSurface"). Entities are ints; a surface is the int id AN_SurfaceId and AN_LandscapeSurface already
// produce. layerMask -1 means every layer. The raycast is an exec node: a cast per pull is too dear to leave to pure evaluation.

inline void appendPhysicalSurfaceNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AN_RaycastSurface", "Raycast Surface", "Physics", {
        pin("exec", "exec", false), pin("originX", "float", false), pin("originY", "float", false), pin("originZ", "float", false),
        pin("dirX", "float", false), pin("dirY", "float", false), pin("dirZ", "float", false),
        pin("maxDist", "float", false, "10000"), pin("layerMask", "int", false, "-1"),
        pin("then", "exec", true), pin("hit", "bool", true), pin("entity", "int", true),
        pin("pointX", "float", true), pin("pointY", "float", true), pin("pointZ", "float", true),
        pin("normalX", "float", true), pin("normalY", "float", true), pin("normalZ", "float", true),
        pin("distance", "float", true), pin("surfaceId", "int", true), pin("friction", "float", true), pin("restitution", "float", true),
        pin("tag", "int", true)}});
    t.push_back({"AN_SurfaceBeneath", "Surface Beneath", "Physics", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("probeCm", "float", false, "150"),
        pin("then", "exec", true), pin("found", "bool", true), pin("surfaceId", "int", true), pin("friction", "float", true),
        pin("restitution", "float", true), pin("tag", "int", true)}});
    t.push_back({"AN_SurfaceInfo", "Surface Info", "Physics", {
        pin("surfaceId", "int", false),
        pin("found", "bool", true), pin("friction", "float", true), pin("restitution", "float", true), pin("tag", "int", true)}});
    t.push_back({"AN_SetBodySurface", "Set Body Surface", "Physics", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("surfaceId", "int", false), pin("copyPhysics", "bool", false, "false"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_RegisterSurface", "Register Surface", "Physics", {
        pin("exec", "exec", false), pin("friction", "float", false, "-1"), pin("restitution", "float", false, "-1"), pin("tag", "int", false, "0"),
        pin("then", "exec", true), pin("surfaceId", "int", true), pin("success", "bool", true)},
        {attr("name", "Name")}});
    t.push_back({"AN_TuneSurface", "Tune Surface", "Physics", {
        pin("exec", "exec", false), pin("surfaceId", "int", false), pin("friction", "float", false), pin("restitution", "float", false),
        pin("tag", "int", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_SetBodyScale", "Set Body Scale", "Physics", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("scaleX", "float", false), pin("scaleY", "float", false),
        pin("scaleZ", "float", false), pin("keepMass", "bool", false, "false"),
        pin("then", "exec", true), pin("success", "bool", true)}});
}
